typeSystemExample.source:
fun <T : Comparable<T>> maxOf(a: T, b: T): T =
    if (a >= b) a else b

fun main() {
    println(maxOf(3, 7))
    println(maxOf(1.5, 2.8))
}

concurrencyExample.source:
import kotlinx.coroutines.*

fun main() = runBlocking {
    val results = (0..3).map { i ->
        async { i * i }
    }
    println(results.map { it.await() }.joinToString(" "))
}
